import{_ as r,o as a,c as e,ak as o}from"./chunks/framework.CMX7UUIo.js";const b=JSON.parse('{"title":"副产物","description":"","frontmatter":{"title":"副产物"},"headers":[],"relativePath":"crops/wheat/by-products.md","filePath":"crops/wheat/by-products.md"}'),p={name:"crops/wheat/by-products.md"};function d(l,t,i,s,n,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="副产物" tabindex="-1">副产物 <a class="header-anchor" href="#副产物" aria-label="Permalink to “副产物”">​</a></h1><p>小麦加工过程中，除主产品面粉外，还会产生麦麸、次粉、胚芽等副产物。这些副产物虽然不是主要商品粉，但具有一定的营养价值和经济价值，常用于饲料加工、食品加工、油脂提取及其他深加工领域。</p><h2 id="麦麸" tabindex="-1">麦麸 <a class="header-anchor" href="#麦麸" aria-label="Permalink to “麦麸”">​</a></h2><p>麦麸是小麦制粉过程中分离出的外层皮壳部分，主要来源于小麦籽粒的麸皮层。</p><p>麦麸通常呈片状、碎片状或细碎屑状，颜色多为浅褐色、黄褐色。其特点是粗纤维含量较高，含有一定的蛋白质、矿物质和维生素。</p><p>麦麸主要用途包括：</p><ol><li><p><strong>饲料原料</strong><br> 常用于猪、牛、羊、禽类等饲料中，可提供纤维、蛋白和部分能量。</p></li><li><p><strong>食品加工</strong><br> 部分优质麦麸可用于全麦食品、膳食纤维产品等。</p></li><li><p><strong>发酵及其他用途</strong><br> 可作为发酵原料或辅料，用于部分农业和工业加工场景。</p></li></ol><p>麦麸的质量通常关注水分、粗蛋白、粗纤维、灰分、霉变、生虫、结块、异味以及呕吐毒素、赤霉烯酮等指标。</p><h2 id="次粉" tabindex="-1">次粉 <a class="header-anchor" href="#次粉" aria-label="Permalink to “次粉”">​</a></h2><p>次粉是小麦制粉过程中产生的低等级粉类副产物，通常由部分粉质、细麸、糊粉层及少量胚乳组成。</p><p>次粉的颜色一般比普通面粉略深，粉质较细，营养成分中含有较高的蛋白质、矿物质和一定量的纤维。由于其中夹杂部分麸皮成分，灰分通常高于普通商品面粉。</p><p>次粉主要用途包括：</p><ol><li><p><strong>饲料加工</strong><br> 是常见的饲料原料，可用于猪料、禽料、水产料等，提供能量和蛋白。</p></li><li><p><strong>工业加工</strong><br> 可用于发酵、酶制剂、淀粉糖等相关加工领域。</p></li><li><p><strong>低端食品或辅料用途</strong><br> 在符合食品安全和质量要求的情况下，可用于部分食品加工辅料。</p></li></ol><p>次粉质量一般关注水分、粗蛋白、灰分、粗纤维、粉色、气味、霉变、生虫及毒素指标。不同厂家、不同等级的次粉质量差异较大，实际交易中需要重点看蛋白、灰分和杂质情况。</p><h2 id="胚芽" tabindex="-1">胚芽 <a class="header-anchor" href="#胚芽" aria-label="Permalink to “胚芽”">​</a></h2><p>小麦胚芽是小麦籽粒中具有发芽能力的部分，位于小麦籽粒的一端，是小麦中营养较集中的部位。</p><p>胚芽含有较丰富的蛋白质、脂肪、维生素E、B族维生素、矿物质等成分，营养价值较高。但由于脂肪含量相对较高，胚芽容易氧化酸败，对储存条件要求较高。</p><p>胚芽主要用途包括：</p><ol><li><p><strong>食品加工</strong><br> 可用于营养食品、谷物食品、烘焙食品、代餐产品等。</p></li><li><p><strong>油脂提取</strong><br> 可用于提取小麦胚芽油，胚芽油中维生素E含量较高。</p></li><li><p><strong>饲料原料</strong><br> 也可作为高营养饲料原料使用，但需要注意新鲜度和酸败问题。</p></li></ol><p>胚芽质量通常关注水分、脂肪含量、气味、色泽、杂质、霉变、酸价和储存稳定性。</p><h2 id="简要对比" tabindex="-1">简要对比 <a class="header-anchor" href="#简要对比" aria-label="Permalink to “简要对比”">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>来源</th><th>主要特点</th><th>主要用途</th></tr></thead><tbody><tr><td>麦麸</td><td>小麦外层皮壳</td><td>粗纤维高，片状或碎屑状</td><td>饲料、食品纤维、发酵辅料</td></tr><tr><td>次粉</td><td>制粉过程中的低等级粉</td><td>蛋白较高，灰分高于普通面粉</td><td>饲料、发酵、工业加工</td></tr><tr><td>胚芽</td><td>小麦籽粒胚部</td><td>营养价值高，脂肪含量较高，易酸败</td><td>食品、胚芽油、饲料</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>麦麸、次粉和胚芽都是小麦加工中的重要副产物。麦麸以纤维和饲料用途为主，次粉兼具能量和蛋白价值，常用于饲料和工业加工；胚芽营养价值较高，可用于食品和油脂深加工。实际采购和使用时，应重点关注水分、蛋白、灰分、纤维、毒素、霉变、气味和储存稳定性等指标。</p>',24)])])}const _=r(p,[["render",d]]);export{b as __pageData,_ as default};
